// Pure: every tunable of the mod, parsed from the plugin's options. Invalid values fall back to the defaults.

import type { Action, Effort, Tier } from './detector'

export type Rates = { input: number; output: number; cacheRead: number; cacheWrite5m: number; cacheWrite1h: number }
export type Price = Rates & { longContext?: Rates & { threshold: number } }

export type Config = {
  threshold: Record<Tier, number>   // difficulty score that triggers the next intervention, per starting tier
  grace: number                     // steps to wait between two interventions
  logSize: number                   // attempts kept in the dossier
  senior: string                    // model asked for advice at the consult level
  maxTier: Tier                     // highest tier a swap may reach (never above opus)
  levels: readonly Action[]         // enabled ladder levels, in escalation order
  prices: Record<Tier, Price>       // USD per million tokens
  prudentTokenRatio: number         // fraction of tokens the baseline model would need
  modelIds: Record<Tier, string>    // full ids sent on a swap when none was observed
  modelOverrides: Partial<Record<Tier, string>>  // explicit ids from the modelIds option; beat observed ids and defaults
  verifyCommand: string           // optional check run at the end of each tracked agent's run; empty = off
  verifyTimeoutSeconds: number      // how long the check may run before it counts as failed (at most 600)
  oscillationEdits: number          // edits of one file made after a failed attempt tolerated since the last progress; each further one adds to the score
  idleSteps: number                 // model requests tolerated without progress
  idleWeight: number                // score added by each model request past idleSteps
  stallMinutes: number              // minutes without any event after which a running agent is flagged as stalled
  maxConsultsPerAgent: number       // senior consults one agent may get; a refused call and its retry count once; 0 = none
  maxConsultsPerSession: number     // senior consults across all agents of the session; 0 = none
  consultBudgetUsd: number          // USD the senior calls may cost in the session; 0 = no limit
  deescalateAfter: number           // progress signals after which a swapped agent goes back one tier; 0 = off
  pauseAtHuman: boolean             // refuse the tool calls of an agent that reached the human level until it is resumed
  effortStep: boolean               // adds the effort level between consult and swap
  effortBoost: Effort               // lowest effort the effort level raises a request to (it always goes at least one step up)
  learningHalfLifeDays: number      // days after which learned evidence counts half; 0 = never fades
  notifyLead: boolean               // message the lead (main conversation) when an agent is swapped up or needs a human
  reviewRate: number                // share (0 to 1) of the runs of cheap models reviewed by a senior model; 0 = off
  reviewModel: string               // model that reviews a sampled run; empty = the senior model
  explore: number                   // weight (0 to 1) of exploring a tier below the learned one at spawn; 0 = off
  respectExplicitModel: boolean     // a model asked for in the Agent call is never changed at spawn by learning or exploration
  learnByCost: boolean              // pick the start tier by cost per accepted run once there is enough cost data
  modelCategories: boolean          // classify tasks with a small model (one short call per uncached spawn) instead of keywords only
  minReviewScore: number            // lowest review score (1 to 5) of an accepted run
  reworkWindowMinutes: number       // minutes after a cheap agent's run during which a lead edit of its files counts as rework; 0 = off
  recordSessions: number            // sessions whose observation stream is recorded for /escalator replay (newest kept); 0 = off
}

// Most sessions the recorder keeps, whatever the option asks for (the store also caps the bytes).
export const MAX_RECORD_SESSIONS = 50

// USD per million tokens, Anthropic API list prices (Oct 2026), checked against /cost.
// Cache writes cost 1.25x input for the 5-minute TTL and 2x input for the 1-hour TTL.
// `longContext` replaces the rates when one request's total input exceeds its threshold.
export const DEFAULT_PRICES: Record<Tier, Price> = {
  opus: { input: 4, output: 20, cacheRead: 0.2, cacheWrite5m: 5, cacheWrite1h: 8 },
  sonnet: { input: 2, output: 10, cacheRead: 0.2, cacheWrite5m: 2.5, cacheWrite1h: 4 },
  haiku: {
    input: 0.1, output: 0.5, cacheRead: 0.01, cacheWrite5m: 0.125, cacheWrite1h: 0.2,
    longContext: { threshold: 100_000, input: 0.5, output: 2.5, cacheRead: 0.05, cacheWrite5m: 0.625, cacheWrite1h: 1 },
  },
}

export const ALL_LEVELS: readonly Action[] = ['nudge', 'consult', 'swap', 'human']
// Every level in escalation order. `effort` is switched by the effortStep option alone, never by `levels`.
const LEVEL_ORDER: readonly Action[] = ['nudge', 'consult', 'effort', 'swap', 'human']
const EFFORT_NAMES: readonly Effort[] = ['low', 'medium', 'high', 'xhigh', 'max']

export const DEFAULT_CONFIG: Config = {
  // Thresholds, oscillation and idle allowance calibrated on a week of observed runs (tests/corpus.test.ts).
  threshold: { haiku: 3, sonnet: 5, opus: 7 },
  grace: 4,
  logSize: 12,
  senior: 'opus',
  levels: ALL_LEVELS,
  maxTier: 'opus',
  prices: DEFAULT_PRICES,
  prudentTokenRatio: 0.65,
  oscillationEdits: 5,
  // The only progress signal is failing tests dropping, so long tasks without tests need headroom: observed runs
  // made 24 requests (median), 49 (p90), 100 at most.
  idleSteps: 60,
  idleWeight: 0.1,
  stallMinutes: 10,
  maxConsultsPerAgent: 3,
  maxConsultsPerSession: 20,
  consultBudgetUsd: 0,
  pauseAtHuman: true,
  deescalateAfter: 0,
  effortStep: false,
  effortBoost: 'high',
  notifyLead: true,
  learningHalfLifeDays: 30,
  modelOverrides: {},
  verifyCommand: '',
  verifyTimeoutSeconds: 120,
  // Off by default: every sampled run costs one senior call.
  reviewRate: 0,
  reviewModel: '',
  // Off by default: exploring deliberately runs some tasks on a model learning had ruled out.
  explore: 0,
  respectExplicitModel: false,
  learnByCost: true,
  modelCategories: false,
  minReviewScore: 3,
  reworkWindowMinutes: 30,
  // Off by default: the recording lives in the plugin's store, next to the learned statistics.
  recordSessions: 0,
  modelIds: { haiku: 'claude-haiku-5-5', sonnet: 'claude-sonnet-5-5', opus: 'claude-opus-5-5' },
}

type Raw = Readonly<Record<string, unknown>>

function num(v: unknown): number | undefined {
  const n = typeof v === 'number' ? v : typeof v === 'string' && v.trim() !== '' ? Number(v) : NaN
  return Number.isFinite(n) ? n : undefined
}

function positive(v: unknown, fallback: number): number {
  const n = num(v)
  return n !== undefined && n > 0 ? n : fallback
}

// A boolean option: a real boolean, or the strings "true" / "false"; anything else keeps the default.
function bool(v: unknown, fallback: boolean): boolean {
  if (typeof v === 'boolean') return v
  const t = typeof v === 'string' ? v.trim().toLowerCase() : ''
  return t === 'true' ? true : t === 'false' ? false : fallback
}

// `effort` is accepted as a name so a list naming it stays valid, but it is ignored here: effortStep adds it.
function parseLevels(v: unknown, fallback: readonly Action[]): readonly Action[] {
  if (typeof v !== 'string' || v.trim() === '') return fallback
  const names = v.split(',').map((s) => s.trim().toLowerCase()).filter(Boolean)
  if (names.length === 0 || names.some((n) => !LEVEL_ORDER.includes(n as Action))) return fallback
  const levels = ALL_LEVELS.filter((l) => names.includes(l))
  return levels.length > 0 ? levels : fallback
}

// The enabled levels in escalation order, with the effort level between consult and swap when it is on.
function withEffort(levels: readonly Action[], on: boolean): readonly Action[] {
  return on ? LEVEL_ORDER.filter((l) => l === 'effort' || levels.includes(l)) : levels
}

function parseEffort(v: unknown, fallback: Effort): Effort {
  const t = typeof v === 'string' ? v.trim().toLowerCase() : ''
  return EFFORT_NAMES.includes(t as Effort) ? (t as Effort) : fallback
}

function parseMaxTier(v: unknown, fallback: Tier): Tier {
  const t = typeof v === 'string' ? v.trim().toLowerCase() : ''
  return t === 'haiku' || t === 'sonnet' || t === 'opus' ? t : fallback
}

const RATE_KEYS = ['input', 'output', 'cacheRead', 'cacheWrite5m', 'cacheWrite1h'] as const

function mergeRates<T extends Rates>(base: T, over: unknown): T {
  if (typeof over !== 'object' || over === null) return base
  const out = { ...base }
  for (const k of RATE_KEYS) {
    const n = num((over as Raw)[k])
    if (n !== undefined && n >= 0) out[k] = n
  }
  return out
}

function mergePrice(base: Price, over: unknown): Price {
  if (typeof over !== 'object' || over === null) return base
  const merged: Price = { ...mergeRates(base, over) }
  if (base.longContext) {
    const lc = (over as Raw).longContext
    const t = num((lc as Raw | undefined)?.threshold)
    merged.longContext = typeof lc === 'object' && lc !== null
      ? { ...mergeRates(base.longContext, lc), threshold: t !== undefined && t > 0 ? t : base.longContext.threshold }
      : base.longContext
  }
  return merged
}

// `prices` is a JSON object keyed by tier, each entry overriding only the rates it names:
// {"sonnet":{"input":3,"output":15}}. Anything malformed is ignored.
function parsePrices(v: unknown, base: Record<Tier, Price>): Record<Tier, Price> {
  if (typeof v !== 'string' || v.trim() === '') return base
  let obj: unknown
  try { obj = JSON.parse(v) } catch { return base }
  if (typeof obj !== 'object' || obj === null) return base
  const o = obj as Raw
  return { haiku: mergePrice(base.haiku, o.haiku), sonnet: mergePrice(base.sonnet, o.sonnet), opus: mergePrice(base.opus, o.opus) }
}

// `modelIds` is a JSON object keyed by tier: {"sonnet":"us.anthropic.claude-sonnet-..."}. Entries that are not
// non-empty strings, and unknown keys, are ignored; malformed JSON gives no overrides.
function parseModelIds(v: unknown): Partial<Record<Tier, string>> {
  if (typeof v !== 'string' || v.trim() === '') return {}
  let obj: unknown
  try { obj = JSON.parse(v) } catch { return {} }
  if (typeof obj !== 'object' || obj === null || Array.isArray(obj)) return {}
  const out: Partial<Record<Tier, string>> = {}
  for (const t of ['haiku', 'sonnet', 'opus'] as const) {
    const id = (obj as Raw)[t]
    if (typeof id === 'string' && id.trim() !== '' && id.length <= 200) out[t] = id.trim()
  }
  return out
}

// Splits a command line into an argument vector: spaces separate, single or double quotes group.
// There is no shell, so no pipes, redirects or variable expansion. An unbalanced quote yields [] (nothing runs).
export function splitCommand(line: string): string[] {
  const out: string[] = []
  let cur = ''
  let inWord = false
  let quote = ''
  for (const ch of line) {
    if (quote) {
      if (ch === quote) quote = ''
      else cur += ch
    } else if (ch === '"' || ch === "'") {
      quote = ch
      inWord = true
    } else if (/\s/.test(ch)) {
      if (inWord) { out.push(cur); cur = ''; inWord = false }
    } else {
      cur += ch
      inWord = true
    }
  }
  if (quote) return []
  if (inWord) out.push(cur)
  return out
}

// The options as the user names them (the `userConfig` keys), with the value in force, read back from a parsed config.
function optionValues(c: Config): [string, unknown][] {
  return [
    ['thresholdHaiku', c.threshold.haiku], ['thresholdSonnet', c.threshold.sonnet], ['thresholdOpus', c.threshold.opus],
    ['graceSteps', c.grace], ['seniorModel', c.senior],
    ['levels', c.levels.filter((l) => l !== 'effort').join(',')], ['maxTier', c.maxTier],
    ['effortStep', c.levels.includes('effort')], ['effortBoost', c.effortBoost],
    ['prudentTokenRatio', c.prudentTokenRatio], ['oscillationEdits', c.oscillationEdits],
    ['idleSteps', c.idleSteps], ['idleWeight', c.idleWeight], ['stallMinutes', c.stallMinutes],
    ['verifyCommand', c.verifyCommand], ['verifyTimeoutSeconds', c.verifyTimeoutSeconds],
    ['maxConsultsPerAgent', c.maxConsultsPerAgent], ['maxConsultsPerSession', c.maxConsultsPerSession],
    ['consultBudgetUsd', c.consultBudgetUsd], ['pauseAtHuman', c.pauseAtHuman], ['notifyLead', c.notifyLead],
    ['deescalateAfter', c.deescalateAfter], ['learningHalfLifeDays', c.learningHalfLifeDays],
    ['reviewRate', c.reviewRate], ['reviewModel', c.reviewModel], ['explore', c.explore],
    ['respectExplicitModel', c.respectExplicitModel], ['learnByCost', c.learnByCost], ['modelCategories', c.modelCategories],
    ['minReviewScore', c.minReviewScore], ['reworkWindowMinutes', c.reworkWindowMinutes],
    ['recordSessions', c.recordSessions],
    ['prices', c.prices], ['modelIds', c.modelOverrides],
  ]
}

// The value in force of one option, by its user-facing name (as /escalator config shows it); undefined for an unknown name.
export function optionValue(c: Config, name: string): unknown {
  return optionValues(c).find(([n]) => n === name)?.[1]
}

function shown(v: unknown): string {
  if (typeof v === 'string') return v === '' ? '(empty)' : v
  return typeof v === 'object' ? JSON.stringify(v) : String(v)
}

// One line per option: `name: value`, plus `(changed, default X)` when it differs from the default.
export function describeConfig(c: Config): string[] {
  const defaults = new Map(optionValues(DEFAULT_CONFIG))
  return optionValues(c).map(([name, v]) => {
    const d = defaults.get(name)
    if (JSON.stringify(v) === JSON.stringify(d)) return `${name}: ${shown(v)}`
    // Long values (prices, model ids, commands) are cut, and their default is not repeated.
    const now = shown(v)
    return now.length > 60 ? `${name}: ${now.slice(0, 57)}... (changed)` : `${name}: ${now} (changed${shown(d).length > 60 ? '' : `, default ${shown(d)}`})`
  })
}

// `fallback` gives the value of every option that is absent or invalid (the defaults unless a caller layers options,
// as the replay does over the options in force).
export function parseConfig(raw: Raw | undefined, fallback: Config = DEFAULT_CONFIG): Config {
  const d = fallback
  const o: Raw = raw ?? {}
  try {
    const ratio = num(o.prudentTokenRatio)
    const grace = num(o.graceSteps)
    const osc = num(o.oscillationEdits)
    const idle = num(o.idleSteps)
    const idleW = num(o.idleWeight)
    const vt = num(o.verifyTimeoutSeconds)
    const vc = typeof o.verifyCommand === 'string' ? o.verifyCommand.trim() : ''
    const senior = typeof o.seniorModel === 'string' ? o.seniorModel.trim() : ''
    const perAgent = num(o.maxConsultsPerAgent)
    const perSession = num(o.maxConsultsPerSession)
    const budget = num(o.consultBudgetUsd)
    const deesc = num(o.deescalateAfter)
    const halfLife = num(o.learningHalfLifeDays)
    const effortStep = bool(o.effortStep, d.effortStep)
    const rate = num(o.reviewRate)
    const explore = num(o.explore)
    const minScore = num(o.minReviewScore)
    const rework = num(o.reworkWindowMinutes)
    const record = num(o.recordSessions)
    const reviewer = typeof o.reviewModel === 'string' ? o.reviewModel.trim() : ''
    return {
      ...d,
      threshold: {
        haiku: positive(o.thresholdHaiku, d.threshold.haiku),
        sonnet: positive(o.thresholdSonnet, d.threshold.sonnet),
        opus: positive(o.thresholdOpus, d.threshold.opus),
      },
      oscillationEdits: osc !== undefined && osc >= 1 ? Math.floor(osc) : d.oscillationEdits,
      idleSteps: idle !== undefined && idle >= 1 ? Math.floor(idle) : d.idleSteps,
      idleWeight: idleW !== undefined && idleW >= 0 ? idleW : d.idleWeight,
      stallMinutes: positive(o.stallMinutes, d.stallMinutes),
      verifyCommand: typeof o.verifyCommand === 'string' && vc.length <= 1000 ? vc : d.verifyCommand,
      verifyTimeoutSeconds: vt !== undefined && vt > 0 ? Math.min(vt, 600) : d.verifyTimeoutSeconds,
      grace: grace !== undefined && grace >= 0 ? Math.floor(grace) : d.grace,
      senior: senior !== '' && senior.length <= 100 ? senior : d.senior,
      levels: withEffort(parseLevels(o.levels, d.levels.filter((l) => l !== 'effort')), effortStep),
      maxTier: parseMaxTier(o.maxTier, d.maxTier),
      prices: parsePrices(o.prices, d.prices),
      modelOverrides: o.modelIds === undefined ? d.modelOverrides : parseModelIds(o.modelIds),
      prudentTokenRatio: ratio !== undefined && ratio > 0 && ratio <= 1 ? ratio : d.prudentTokenRatio,
      maxConsultsPerAgent: perAgent !== undefined && perAgent >= 0 ? Math.floor(perAgent) : d.maxConsultsPerAgent,
      maxConsultsPerSession: perSession !== undefined && perSession >= 0 ? Math.floor(perSession) : d.maxConsultsPerSession,
      consultBudgetUsd: budget !== undefined && budget >= 0 ? budget : d.consultBudgetUsd,
      pauseAtHuman: bool(o.pauseAtHuman, d.pauseAtHuman),
      deescalateAfter: deesc !== undefined && deesc >= 1 ? Math.floor(deesc) : d.deescalateAfter,
      effortStep,
      effortBoost: parseEffort(o.effortBoost, d.effortBoost),
      notifyLead: bool(o.notifyLead, d.notifyLead),
      learningHalfLifeDays: halfLife !== undefined && halfLife >= 0 ? halfLife : d.learningHalfLifeDays,
      reviewRate: rate !== undefined && rate >= 0 && rate <= 1 ? rate : d.reviewRate,
      explore: explore !== undefined && explore >= 0 && explore <= 1 ? explore : d.explore,
      respectExplicitModel: bool(o.respectExplicitModel, d.respectExplicitModel),
      learnByCost: bool(o.learnByCost, d.learnByCost),
      modelCategories: bool(o.modelCategories, d.modelCategories),
      minReviewScore: minScore !== undefined && minScore >= 1 && minScore <= 5 ? minScore : d.minReviewScore,
      reworkWindowMinutes: rework !== undefined && rework >= 0 ? rework : d.reworkWindowMinutes,
      recordSessions: record !== undefined && record >= 0 ? Math.min(Math.floor(record), MAX_RECORD_SESSIONS) : d.recordSessions,
      reviewModel: typeof o.reviewModel === 'string' && reviewer.length <= 100 ? reviewer : d.reviewModel,
    }
  } catch {
    return d
  }
}

files.hooks/detector.ts:
// Pure logic: no $ calls, so it is unit-testable in isolation.

import { DEFAULT_CONFIG, type Config } from './config'
import { exitCodes, hashKey, outputPrint, parseTestRuns, softFailure } from './testparse'

export type Tier = 'haiku' | 'sonnet' | 'opus'
export const LADDER: readonly Tier[] = ['haiku', 'sonnet', 'opus']

export type Action = 'nudge' | 'consult' | 'effort' | 'swap' | 'human'

// The effort scale of a model request, lowest first. A request may also carry a number, or no effort at all
// (a model that takes none): neither can be raised.
export type Effort = 'low' | 'medium' | 'high' | 'xhigh' | 'max'
export const EFFORTS: readonly Effort[] = ['low', 'medium', 'high', 'xhigh', 'max']

// The effort to send instead of `current`: one step above it, and at least `floor`. Undefined when it cannot be
// raised: no effort (the model takes none), a number, an unknown value, or already at the top of the scale.
export function raiseEffort(current: unknown, floor: Effort): Effort | undefined {
  const i = EFFORTS.indexOf(current as Effort)
  if (i < 0 || i === EFFORTS.length - 1) return undefined
  return EFFORTS[Math.max(i + 1, EFFORTS.indexOf(floor))]
}

export type AgentState = {
  id: string
  category: string
  task: string
  startTier: Tier
  tier: Tier
  score: number
  level: number
  stepsSinceAction: number
  stepsSinceProgress: number            // model requests since the last progress; past the idle allowance each adds to the score
  errorCounts: Record<string, number>
  editCounts: Record<string, number>   // edits per normalised file path since the last progress
  retryEdits?: Record<string, number>   // of those, the edits made after a failed attempt (since the file's previous edit)
  editMarks?: Record<string, number>    // failed attempts since the last progress at the last edit of each file
  lastFailing?: number
  requests?: number                     // model requests the agent started: the assistant message its next tool calls belong to
  messageCalls?: number                 // tool calls started since the latest request began
  messageTools?: number                 // tool calls the latest request asked for, once it ended
  message?: number                      // the assistant message of the agent's last tool call that had one
  messageSigs?: string[]                // error signatures (and output prints, "o:" first) already counted in that message
  // Failure outputs of shell calls that exited 0, by output print since the last progress: the command hash and the
  // number of edits at the latest sighting. Absent until the first such output.
  outputs?: Record<string, { c: string; e: number }>
  log: string[]
  tokens: number
  // Liveness, for stall detection. All optional: snapshots saved before they existed lack them.
  lastEventAt?: number                  // $.clock.now() of the agent's last event (spawn, tool call start or end, model request)
  inFlight?: number                     // tool calls started and not yet finished
  running?: boolean                     // true from the first event of a run until turn.complete
  stalled?: boolean                     // already flagged as silent; cleared by any event
  helped?: boolean                      // asked for help through the tool at least once
  recentErrors?: string[]               // full text (cut) of the last failed calls, oldest first, for the senior dossier
  consults?: number                     // senior consult actions for this agent (a refused call and its retry count once)
  paused?: boolean                      // stopped at the human level: its tool calls are refused until the user resumes it
  progressSignals?: number              // progress signals since the last swap (or de-escalation), counted only while the agent runs above its start tier
  deescalated?: boolean                 // already returned to a cheaper tier in this run: never again until the run is over
  effortSeen?: Effort | number | null   // effort of the agent's last model request as the engine set it; null when it had none
  effortBoosted?: boolean               // the effort level acted: its requests carry a raised effort until the next swap
  name?: string                         // the name the agent was spawned with (Agent's `name`), capped; per session, never in the stats
  taskTitle?: string                    // subject of the shared-list task it created or claimed (in_progress), capped
}

// Names and task titles are shown in one log line or notice each, so they are capped.
export const MAX_AGENT_NAME = 40
export const MAX_TASK_TITLE = 80

// Flattens whitespace and cuts to `max` characters, the cut marked with "...". Undefined for a non-string or a blank one.
export function clipLabel(v: unknown, max: number): string | undefined {
  if (typeof v !== 'string') return undefined
  const flat = v.replace(/\s+/g, ' ').trim()
  if (flat === '') return undefined
  return flat.length > max ? `${flat.slice(0, max - 3)}...` : flat
}

// The label of a spawned agent: its explicit name, else the short description of its task, both capped.
export function spawnName(e: { name?: unknown; description?: unknown }): string | undefined {
  return clipLabel(e.name, MAX_AGENT_NAME) ?? clipLabel(e.description, MAX_AGENT_NAME)
}

// The agent as the lead reads it: `name (id)` when it has a name, else the id.
export function agentHead(s: { id: string; name?: string }): string {
  return s.name ? `${s.name} (${s.id})` : s.id
}

// The agent's head, then its task title when one is known: `fixer (a1) · task: Fix the date parser`.
export function agentLabel(s: { id: string; name?: string; taskTitle?: string }): string {
  return s.taskTitle ? `${agentHead(s)} · task: ${s.taskTitle}` : agentHead(s)
}

// The task an agent works on, read from its call of a task-list tool. A task it creates is its own. TaskUpdate to
// in_progress claims the task, titled by the call's subject or else by the subject the list gave that id (`subjects`).
export function taskClaim(tool: unknown, input: Record<string, unknown>, subjects: ReadonlyMap<string, string>): string | undefined {
  if (tool === 'TaskCreate') return clipLabel(input.subject, MAX_TASK_TITLE)
  if (tool === 'TaskUpdate' && input.status === 'in_progress') {
    return clipLabel(input.subject, MAX_TASK_TITLE) ?? subjects.get(String(input.taskId))
  }
  return undefined
}

// The id and subject of the task a task-list answer carries (`task` in TaskCreate's or TaskGet's result).
export function taskOfResult(result: unknown): { id: string; subject: string } | undefined {
  if (typeof result !== 'object' || result === null) return undefined
  const t = (result as { task?: unknown }).task
  if (typeof t !== 'object' || t === null) return undefined
  const { id, subject } = t as { id?: unknown; subject?: unknown }
  const text = typeof id === 'string' ? id : typeof id === 'number' ? String(id) : undefined
  const title = clipLabel(subject, MAX_TASK_TITLE)
  return text !== undefined && title !== undefined ? { id: text, subject: title } : undefined
}

export function tierOf(model: string | undefined): Tier {
  const m = (model ?? '').toLowerCase()
  if (m.includes('haiku')) return 'haiku'
  if (m.includes('opus') || m.includes('mythos') || m.includes('fable')) return 'opus'
  return 'sonnet'
}

export type ObservedModels = Partial<Record<Tier, string>> & { leadShape?: string }

// Provider shape of an id: whatever precedes "claude-" ("us.anthropic." on Bedrock, "" for first-party and Vertex ids).
const shapeOf = (lower: string): string => lower.slice(0, lower.indexOf('claude-'))

// Remembers a resolved full id (never a bare alias such as "sonnet") under its own tier. Any provider prefix or
// suffix is fine (Bedrock region prefixes, "anthropic.", "@date", "-v1:0", "[1m]"): the family word must follow "claude-".
// `isLead` marks the id as the lead's own: its shape is then preferred, so a Bedrock lead keeps Bedrock-shaped targets
// even when an id of another shape shows up later for the same tier.
export function rememberModel(seen: ObservedModels, model: string | undefined, isLead = false): ObservedModels {
  const m = (model ?? '').trim()
  const lower = m.toLowerCase()
  const at = lower.indexOf('claude-')
  if (at < 0) return seen
  // Only the ladder's own families: fable/mythos/unknown ids must never become a swap target.
  if (lower.includes('fable') || lower.includes('mythos')) return seen
  const tier = LADDER.find((t) => lower.indexOf(t, at + 7) >= 0)
  if (!tier) return seen
  const next: ObservedModels = { ...seen }
  if (isLead) next.leadShape = shapeOf(lower)
  const kept = seen[tier]
  const keepsLead = kept !== undefined && next.leadShape !== undefined
    && shapeOf(kept.toLowerCase()) === next.leadShape && shapeOf(lower) !== next.leadShape
  if (!keepsLead) next[tier] = m
  return next
}

// Full model id to send for a tier: the user's explicit id, else the one observed in this session, else the default.
export function resolveModelId(seen: ObservedModels, tier: Tier, ids: Record<Tier, string> = DEFAULT_CONFIG.modelIds,
  overrides: Partial<Record<Tier, string>> = {}): string {
  return overrides[tier] ?? seen[tier] ?? ids[tier]
}

export const tierRank = (t: Tier): number => LADDER.indexOf(t)

export function nextTier(t: Tier): Tier {
  const i = LADDER.indexOf(t)
  return LADDER[Math.min(i + 1, LADDER.length - 1)]!
}

export function newAgent(id: string, category: string, model: string | undefined, task: string): AgentState {
  const t = tierOf(model)
  return { id, category, task: task.slice(0, 2000), startTier: t, tier: t, score: 0, level: 0,
    stepsSinceAction: 0, stepsSinceProgress: 0, errorCounts: {}, editCounts: {}, log: [], tokens: 0 }
}

// Strips what changes between identical failures: numbers, paths, hex ids, spacing.
export function normalizeError(text: string): string {
  return text
    .replace(/(\/[\w.@-]+)+/g, '<path>')
    .replace(/0x[0-9a-f]+/gi, '<hex>')
    .replace(/\d+/g, '<n>')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 160)
}

export function failingTests(text: string): number | undefined {
  const m = text.match(/(\d+)\s+(?:failed|failing|failures?)\b/i)
  if (m) return Number(m[1])
  if (/\b(\d+)\s+passed\b/i.test(text) && !/fail/i.test(text)) return 0
  return undefined
}

const EDIT_TOOLS = ['Edit', 'Write', 'MultiEdit', 'NotebookEdit']

// One key per file: forward slashes, case-folded for Windows-style paths (case-insensitive file systems).
export function normalizePath(p: string): string {
  const t = p.trim()
  const f = t.replace(/\\/g, '/')
  return f !== t || /^[a-z]:\//i.test(f) ? f.toLowerCase() : f
}

// The action due at the current level, moving s.level past it. While the agent runs below `maxTier`,
// the ladder keeps swapping one tier up instead of moving past the swap level. A swap that cannot happen
// (swap disabled, or the agent already at `maxTier`) is skipped, and the next enabled level acts in its place.
// A consult that is closed (a limit was reached) is skipped the same way: `skipped` reports it. So is an effort
// level that cannot act: the effort is already raised, or the agent's last request had none that can be raised.
function nextAction(s: AgentState, cfg: Config, consultOpen: boolean, blocked: readonly Tier[]): { action?: Action; skipped: boolean } {
  const swapAt = cfg.levels.indexOf('swap')
  const canSwap = swapAt >= 0 && tierRank(s.tier) < tierRank(allowedMax(cfg.maxTier, blocked))
  if (canSwap && s.level > swapAt) return { action: 'swap', skipped: false }   // level stays just past the swap
  let skipped = false
  while (s.level < cfg.levels.length) {
    const action = cfg.levels[s.level]!
    s.level++
    if (action === 'consult' && !consultOpen) { skipped = true; continue }
    if (action === 'effort' && !canRaiseEffort(s, cfg)) continue
    if (action !== 'swap' || canSwap) return { action, skipped }
  }
  return { skipped }
}

// Why no further senior consult may be made, or undefined when one may. `sessionConsults` is the total over
// all agents; `consultCost` the USD of every senior call so far (a refused call and its retry both count).
// A count limit of 0 allows no consult; a budget of 0 means no dollar limit.
export function consultLimit(s: AgentState, sessionConsults: number, consultCost: number, cfg: Config = DEFAULT_CONFIG): string | undefined {
  if ((s.consults ?? 0) >= cfg.maxConsultsPerAgent) return `per agent (${cfg.maxConsultsPerAgent} consults)`
  if (sessionConsults >= cfg.maxConsultsPerSession) return `per session (${cfg.maxConsultsPerSession} consults)`
  if (cfg.consultBudgetUsd > 0 && consultCost >= cfg.consultBudgetUsd) return `budget (USD ${cfg.consultBudgetUsd})`
  return undefined
}

export const MAX_RECENT_ERRORS = 6
export const MAX_ERROR_TEXT = 2000

// Keeps the head and the tail of a long error text (the cause is often at the end), within MAX_ERROR_TEXT.
function cutError(text: string): string {
  if (text.length <= MAX_ERROR_TEXT) return text
  const mark = '\n[... cut ...]\n'
  const room = MAX_ERROR_TEXT - mark.length
  const head = Math.floor(room * 0.45)
  return text.slice(0, head) + mark + text.slice(text.length - (room - head))
}

// `group`: the assistant message the call belongs to (the agent's model requests started before the call), when known.
export type Observation = { tool: string; ok: boolean; text: string; summary: string; group?: number }

// What the score reads from one tool result, without its text: the failed attempts in it, the signature of its
// error (empty when nothing failed), the failing count of each test run in it, the edited file (normalised; only
// for an edit tool) and the assistant message it belongs to. `env` marks a call the environment refused before it
// did anything. `out` and `cmd` (hashes) mark a shell call that exited 0 with no failed attempt and no test summary, but
// whose output reports a failure in its own words: its output print and its command. The recorder keeps these, so a
// replay scores exactly what the live detector scored.
export type Features = { attempts: number; sig: string; counts: number[]; edit?: string; env?: true; group?: number; out?: string; cmd?: string }

// How the agent's log marks a soft failure after "ok": the call exited 0, its output reports a failure. The dossier
// reads it back to show that output to the senior.
export const SOFT_FAILURE_MARK = '(the output reports a failure)'

// Tools whose result is the output of a command the agent chose.
const SHELL_TOOLS = ['Bash', 'PowerShell']

// What a repeated failure output adds to the score. Half of a repeated error: the verdict is read from words, not
// from an exit code, so it takes six repeats to reach Haiku's threshold on its own.
export const REPEAT_OUTPUT_WEIGHT = 0.5
// Failure outputs remembered per agent (the latest ones).
export const MAX_OUTPUTS = 20

// Programs that only show or search what exists. Run first in a command, they read: their output naming a failure
// (a source file, a log, a diff) is no attempt of the agent's, however often it comes back.
const READERS = new Set(['cat', 'head', 'tail', 'less', 'more', 'grep', 'egrep', 'fgrep', 'rg', 'ag', 'awk', 'find', 'ls', 'wc', 'diff',
  'jq', 'type', 'get-content', 'select-string'])
const GIT_READS = new Set(['log', 'show', 'diff', 'status', 'blame', 'grep'])
// git's own options that take a value as the next word.
const GIT_VALUE_OPTIONS = new Set(['-C', '-c', '--git-dir', '--work-tree', '--namespace'])

// Shell words, quotes kept together; runs of | ; & are one word each.
const words = (cmd: string): string[] => cmd.match(/"[^"]*"|'[^']*'|[|;&]+|[^\s|;&]+/g) ?? []
const isOperator = (w: string): boolean => /^[|;&]+$/.test(w)

// True when the command's first program only reads: a viewer or a search from READERS, `sed -n` (without -i), or a
// read-only git subcommand. `cd dir &&` (or `;`) prefixes and leading VAR=value assignments are skipped; what the
// first program is piped into does not matter (`bash check.sh | tail -1` runs a check, `cat log | grep FAIL` reads).
// Pure; never throws.
export function readOnlyCommand(cmd: string): boolean {
  try {
    if (typeof cmd !== 'string') return false
    let w = words(cmd)
    for (;;) {
      if (w[0] === 'cd' && w.length >= 3 && (w[2] === '&&' || w[2] === ';')) { w = w.slice(3); continue }
      if (w[0] !== undefined && /^[A-Za-z_]\w*=/.test(w[0])) { w = w.slice(1); continue }
      break
    }
    const first = w.findIndex(isOperator)
    const args = (first < 0 ? w : w.slice(0, first)).map((x) => x.replace(/^["']|["']$/g, ''))
    const program = (args[0] ?? '').split(/[\\/]/).pop()!.toLowerCase().replace(/\.exe$/, '')
    if (READERS.has(program)) return true
    if (program === 'sed') {
      const quiet = args.slice(1).some((a) => /^-[A-Za-z]*n[A-Za-z]*$/.test(a) || a === '--quiet' || a === '--silent')
      const inPlace = args.slice(1).some((a) => /^-[A-Za-z]*i/.test(a) || a.startsWith('--in-place'))
      return quiet && !inPlace
    }
    if (program === 'git') {
      let i = 1
      while (i < args.length && args[i]!.startsWith('-')) i += GIT_VALUE_OPTIONS.has(args[i]!) ? 2 : 1
      return GIT_READS.has(args[i] ?? '')
    }
    return false
  } catch {
    return false
  }
}

// One key per command line: the same command with other spacing is the same command.
export function normalizeCommand(cmd: string): string {
  return typeof cmd === 'string' ? cmd.replace(/\s+/g, ' ').trim() : ''
}

// Refusals by Claude Code itself (a permission rule or prompt, the auto mode classifier, a safety check, the worktree
// guard, a hook, a stale or unread file, a standalone sleep, the mod's own pause): the tool never ran, so the result
// says nothing about the agent's work. Each pattern is anchored at the start of the result, where the engine puts its
// refusal; a failure of the tool itself starts otherwise ("Exit code 1", the program's own output).
const ENVIRONMENT_ERRORS: readonly RegExp[] = [
  /^This agent is isolated in the worktree\b[\s\S]*\bRefusing to run it\b/,
  /^Refusing to use \S+ as an isolation worktree\b/,
  /^Permission for this (?:action|command) (?:was|has been) denied\b/,
  /^Permission to use \S+(?: with command [\s\S]*?)? has been denied\./,
  /^[^\n]{1,400} was blocked by a deny rule\b/,
  /^The server-side auto mode classifier gave no verdict\b/,
  /^The user doesn't want to proceed with this tool use\b/,
  /^This \S+ command contains multiple operations\. The following parts? requires? approval\b/,
  /^(?:PreToolUse|PermissionRequest)(?::\S+)? hook (?:error|blocking error|did not respond)\b/,
  /^Operation stopped by hook\b/,
  /^(?:<tool_use_error>)?(?:Error: )?File has been modified since read\b/,
  /^(?:<tool_use_error>)?(?:Error: )?File has not been read yet\b/,
  /^(?:<tool_use_error>)?Blocked: (?:standalone )?sleep \d/,
  /^(?:<tool_use_error>)?\[supervisor:[0-9a-f]{6}\] You are paused\b/,
]

// True when a failed tool result is a refusal of the environment rather than a failure of the agent's work. Pure.
export function environmentError(text: string): boolean {
  if (typeof text !== 'string') return false
  const t = text.trimStart()
  return t !== '' && ENVIRONMENT_ERRORS.some((p) => p.test(t))
}

export function features(ob: Observation): Features {
  // A refused call did nothing: no attempt, no error, no test run, no edit.
  if (!ob.ok && environmentError(ob.text)) return { attempts: 0, sig: '', counts: [], env: true }
  // Failing counts per test run in the output; plain text without a recognised summary falls back
  // to the first "N failed" it mentions.
  const runs = parseTestRuns(ob.text)
  const counts = runs.length > 0 ? runs.map(r => r.failed) : [failingTests(ob.text)].filter((n): n is number => n !== undefined)
  // Failed attempts in this output. An isError result is one attempt. A loop (or `; echo "exit=$?"`)
  // can hide failures behind ok=true, so every failing run and every non-zero exit marker counts as
  // well. The largest of the three wins, they are never summed, so one failed attempt weighs once
  // here (plus once more when its failing count does not drop).
  const failedRuns = runs.filter(r => r.failed > 0).length
  const badExits = exitCodes(ob.text).filter(c => c !== 0).length
  const attempts = Math.max(ob.ok ? 0 : 1, failedRuns, badExits)
  const f: Features = { attempts, sig: attempts > 0 ? normalizeError(ob.text) : '', counts }
  if (EDIT_TOOLS.includes(ob.tool) && ob.summary) f.edit = normalizePath(ob.summary)
  if (typeof ob.group === 'number' && Number.isFinite(ob.group)) f.group = ob.group
  // A command that exits 0 can still fail (piped into `tail`, `|| true`, a script that always exits 0): when nothing
  // else read a verdict in it and its output reports a failure, keep its print to see whether it comes back. A command
  // that only reads (cat, grep, git diff, ...) tries nothing: a failure it shows is not the agent's attempt.
  if (ob.ok && attempts === 0 && counts.length === 0 && SHELL_TOOLS.includes(ob.tool) && !readOnlyCommand(ob.summary) && softFailure(ob.text)) {
    f.out = outputPrint(ob.text)
    f.cmd = hashKey(normalizeCommand(ob.summary))
  }
  return f
}

// Which assistant message a tool call belongs to. There is no message id on tool.call, but an agent's calls all start
// after the model request that asked for them began and before its next request begins, and the request's result
// lists the calls it asked for. So a call belongs to the agent's latest request while that request has calls left;
// past them, or before any request was seen, it belongs to no known message (and every call counts on its own).

// One model request of an agent starts: the tool calls it asks for belong to this request's message.
export function beginRequest<T extends AgentState>(s: T): T {
  const { messageTools: _known, ...rest } = s
  return { ...rest, requests: (s.requests ?? 0) + 1, messageCalls: 0 } as T
}

// The request ended asking for `toolUses` tool calls.
export function endRequest<T extends AgentState>(s: T, toolUses: number): T {
  return { ...s, messageTools: toolUses }
}

// A tool call of the agent starts: its message, when it can belong to the latest request.
export function startCall<T extends AgentState>(s: T): { state: T; group?: number } {
  const calls = (s.messageCalls ?? 0) + 1
  const state = { ...s, messageCalls: calls }
  if (s.requests === undefined || (s.messageTools !== undefined && calls > s.messageTools)) return { state }
  return { state, group: s.requests }
}

const failedSoFar = (s: AgentState): number => Object.values(s.errorCounts).reduce((n, c) => n + c, 0)
const editsSoFar = (s: AgentState): number => Object.values(s.editCounts).reduce((n, c) => n + c, 0)

// Same output repeated: a shell call exited 0 but its output reports a failure, and that very output (`out`, its print)
// came back for a new attempt: another command, or the same one after an edit. The agent changed something and got
// the same failure, so it is not making progress even though nothing exited non-zero. The same command with no edit in
// between is a re-read (polling a log, checking a status) and adds nothing; so does a repeat within one assistant
// message (parallel calls). Mutates `s`, a copy owned by decide.
function seeOutput(s: AgentState, out: string, cmd: string, group: number | undefined): void {
  if (group !== undefined) {
    const key = `o:${out}`
    if ((s.messageSigs ?? []).includes(key)) return
    s.messageSigs = [...(s.messageSigs ?? []), key].slice(-20)
  }
  const edits = editsSoFar(s)
  const seen = s.outputs?.[out]
  if (seen && (seen.c !== cmd || edits > seen.e)) s.score += REPEAT_OUTPUT_WEIGHT
  // The latest sighting goes last, so the oldest outputs are the first forgotten.
  const outputs = Object.entries(s.outputs ?? {}).filter(([k]) => k !== out)
  outputs.push([out, { c: cmd, e: edits }])
  s.outputs = Object.fromEntries(outputs.slice(-MAX_OUTPUTS))
}

// Progress, a resume or a de-escalation forgets the failure outputs seen (only on an agent that has any).
const noOutputs = (s: AgentState): Pick<AgentState, 'outputs'> => (s.outputs !== undefined ? { outputs: {} } : {})

// What progress (or a fresh ladder) forgets of the agent's edits.
const noEdits = (): Pick<AgentState, 'editCounts' | 'editMarks' | 'retryEdits'> => ({ editCounts: {}, editMarks: {}, retryEdits: {} })

type Decision = { state: AgentState; action?: Action; consultSkipped?: boolean; progress?: boolean }

// `consultOpen` false means a limit forbids consults now: a consult due at this trigger is skipped to the next
// enabled level, and `consultSkipped` tells the caller that a limit stopped it.
// `blocked` lists the tiers the account refused this session: a swap never reaches them, nor any tier above.
// `f` is the call's features when the caller already read them (the recorder does).
export function observe(prev: AgentState, ob: Observation, cfg: Config = DEFAULT_CONFIG, consultOpen = true, blocked: readonly Tier[] = [], f: Features = features(ob)): Decision {
  const out = decide(prev, f, cfg, consultOpen, blocked)
  const verdict = f.env ? 'refused by the environment'
    : f.attempts > 0 ? 'ERR ' + f.sig.slice(0, 100)
      : f.out !== undefined ? `ok ${SOFT_FAILURE_MARK}` : 'ok'
  const log = [...prev.log, `${ob.tool}: ${ob.summary.slice(0, 120)} -> ${verdict}`]
  if (log.length > cfg.logSize) log.splice(0, log.length - cfg.logSize)
  out.state.log = log
  // One ring entry per failed log line (same rule as the "ERR" mark above) and per soft failure (marked
  // SOFT_FAILURE_MARK), so the dossier can match them from the end.
  if (f.attempts > 0 || f.out !== undefined) out.state.recentErrors = [...(prev.recentErrors ?? []), cutError(String(ob.text ?? ''))].slice(-MAX_RECENT_ERRORS)
  return out
}

// The score and the ladder decision of one tool result, from its features alone (no log, no error text): what
// observe decides live, and what a replay decides with another configuration.
export function decide(prev: AgentState, f: Features, cfg: Config = DEFAULT_CONFIG, consultOpen = true, blocked: readonly Tier[] = []): Decision {
  // A call the environment refused is no step of the agent's work: nothing changes, not even the grace window.
  if (f.env) return { state: { ...prev } }
  const s: AgentState = { ...prev, errorCounts: { ...prev.errorCounts }, editCounts: { ...prev.editCounts } }
  s.stepsSinceAction++
  let progress = false
  const failedBefore = failedSoFar(s)

  // Calls of one assistant message run in parallel: the same failure seen again in the same message is one failure,
  // so such a repeat adds nothing (neither for its error nor for its test count).
  let repeat = false
  if (f.group !== undefined) {
    if (s.message !== f.group) { s.message = f.group; s.messageSigs = [] }
    if (f.attempts > 0) {
      repeat = (s.messageSigs ?? []).includes(f.sig)
      if (!repeat) s.messageSigs = [...(s.messageSigs ?? []), f.sig].slice(-20)
    }
  }

  for (let i = 0; i < (repeat ? 0 : f.attempts); i++) {
    const n = (s.errorCounts[f.sig] ?? 0) + 1
    s.errorCounts[f.sig] = n
    s.score += n >= 2 ? 1 : 0.25
  }

  if (f.out !== undefined) seeOutput(s, f.out, f.cmd ?? '', f.group)

  // Oscillation: the same file edited again and again without progress, whatever the errors say. Only an edit made
  // after a failed attempt (since the previous edit of that file) counts: a run of edits with no failure is work.
  if (f.edit !== undefined) {
    s.editCounts[f.edit] = (s.editCounts[f.edit] ?? 0) + 1
    if (failedBefore > (s.editMarks?.[f.edit] ?? 0)) {
      const retries = s.retryEdits?.[f.edit] ?? 0
      if (retries >= cfg.oscillationEdits) s.score += 1
      s.retryEdits = { ...s.retryEdits, [f.edit]: retries + 1 }
    }
    s.editMarks = { ...s.editMarks, [f.edit]: failedBefore }
  }

  // Runs are applied in order. Progress wipes the score; later runs of the same output that do not
  // improve on the new baseline count again, so only the end state decides whether the call was progress.
  // A count that goes up (new failing tests, as in the red phase of TDD) adds nothing by itself.
  for (const failing of repeat ? [] : f.counts) {
    if (failing === 0 || (s.lastFailing !== undefined && failing < s.lastFailing)) {
      progress = true
      Object.assign(s, { score: 0, errorCounts: {}, ...noEdits(), ...noOutputs(s) })
    } else if (s.lastFailing !== undefined) {
      if (failing === s.lastFailing) s.score += 1
      progress = false
    }
    s.lastFailing = failing
  }

  if (progress) {
    Object.assign(s, { score: 0, stepsSinceProgress: 0, errorCounts: {}, ...noEdits(), ...noOutputs(s) })
    return { state: s, progress: true }
  }

  const due = s.level === 0 || s.stepsSinceAction >= cfg.grace
  if (s.score >= cfg.threshold[s.tier] && due) {
    const pick = nextAction(s, cfg, consultOpen, blocked)
    if (pick.action) {
      s.score = 0
      s.stepsSinceAction = 0
      // A swap drops a raised effort: the new model starts from the request's own effort.
      if (pick.action === 'swap') { s.tier = nextTier(s.tier); s.progressSignals = 0; s.effortBoosted = false }
      if (pick.action === 'effort') s.effortBoosted = true
      return { state: s, action: pick.action, consultSkipped: pick.skipped }
    }
    return { state: s, consultSkipped: pick.skipped }
  }
  return { state: s }
}

// The end of an agent's run (turn.complete): a fresh ladder for its next run. The tier, a pause and the
// counters that outlive a run (consults, failures since the last progress) are kept.
export function endRun<T extends AgentState>(s: T): T {
  return { ...s, level: 0, score: 0, stepsSinceAction: 0, deescalated: false, progressSignals: 0, running: false, inFlight: 0, stalled: false }
}

// The effort level may act: not yet raised on this tier, and the agent's last request carried an effort below the top.
export function canRaiseEffort(s: AgentState, cfg: Config = DEFAULT_CONFIG): boolean {
  return s.effortBoosted !== true && raiseEffort(s.effortSeen, cfg.effortBoost) !== undefined
}

// One model request of a tracked agent. Requests beyond the idle allowance without progress add to the score,
// so an agent that keeps working without ever producing a result climbs the ladder too.
export function countStep(prev: AgentState, cfg: Config = DEFAULT_CONFIG): AgentState {
  const s: AgentState = { ...prev, stepsSinceProgress: prev.stepsSinceProgress + 1 }
  if (s.stepsSinceProgress > cfg.idleSteps) s.score += cfg.idleWeight
  return s
}

// Any event of the agent: it is running, not silent, and no longer flagged.
export function touch(s: AgentState, now: number): AgentState {
  return { ...s, lastEventAt: now, running: true, stalled: false }
}

export function toolStart(s: AgentState, now: number): AgentState {
  return { ...touch(s, now), inFlight: (s.inFlight ?? 0) + 1 }
}

export function toolEnd(s: AgentState, now: number): AgentState {
  return { ...touch(s, now), inFlight: Math.max(0, (s.inFlight ?? 0) - 1) }
}

// A tool call in flight (a build, a test suite) is legitimate silence: the window is three times longer,
// so only a call that hangs for very long is flagged.
export const BUSY_FACTOR = 3

// How long (ms) a running, not yet flagged agent has been silent, when that exceeds its window; else undefined.
// An agent without a timestamp (old snapshot) or whose run is over is never silent.
export function isSilent(s: AgentState, now: number, cfg: Config = DEFAULT_CONFIG): number | undefined {
  if (!s.running || s.stalled || s.paused || s.lastEventAt === undefined) return undefined
  const window = cfg.stallMinutes * 60_000 * ((s.inFlight ?? 0) > 0 ? BUSY_FACTOR : 1)
  const silent = now - s.lastEventAt
  return silent > window ? silent : undefined
}

// The silence window of a running agent starts again now: a gap that says nothing about the agent (the account at
// its usage limit, the session closed or reloaded) is never counted as its silence.
export function restartSilence<T extends AgentState>(s: T, now: number): T {
  return s.running ? { ...s, lastEventAt: now } : s
}

// The session ended: whatever ran is over (its next event, after a resume, starts a new run for the stall check).
export function sessionClosed<T extends AgentState>(s: T): T {
  return { ...s, running: false, inFlight: 0, stalled: false }
}

// True when a rate-limit window of the account (`$.session.usage().rateLimits`) is used up: agents then wait for the
// limit, they are not stuck.
export function limitReached(rateLimits: unknown): boolean {
  return Array.isArray(rateLimits) && rateLimits.some((w) =>
    typeof w === 'object' && w !== null && typeof (w as { percentUsed?: unknown }).percentUsed === 'number' && (w as { percentUsed: number }).percentUsed >= 100)
}

// Flags the agent. A silent agent with no tool call running also gets its score raised to its threshold, so its
// next tool call earns the next ladder note. With a tool call in flight the command may simply be slow: only
// flag it (the lead is notified); if the command fails, the usual error signals take over.
export function markStall(s: AgentState, cfg: Config = DEFAULT_CONFIG): AgentState {
  if ((s.inFlight ?? 0) > 0) return { ...s, stalled: true }
  return { ...s, stalled: true, score: Math.max(s.score, cfg.threshold[s.tier]) }
}

// The agent reached the human level: it is paused until the user resumes it.
export function pauseAgent(s: AgentState): AgentState {
  return { ...s, paused: true }
}

// The user resumed the agent: it keeps its tier and starts a fresh ladder (no score, no failure history, a fresh
// grace window). With `now` it also counts as active then, so the pause itself is never read as silence.
export function resumeAgent(s: AgentState, now?: number): AgentState {
  const { paused: _paused, lastFailing: _lastFailing, ...rest } = s
  const fresh: AgentState = { ...rest, score: 0, level: 0, stepsSinceAction: 0, stepsSinceProgress: 0, errorCounts: {}, ...noEdits(), ...noOutputs(s), stalled: false }
  return now === undefined ? fresh : { ...fresh, lastEventAt: now }
}

// One progress signal of an agent. While it runs above its start tier (in `observe`, where the tier never
// changes, while its ladder is past the swap level) signals are counted; at `deescalateAfter` the agent goes back
// ONE tier, towards its start tier, with a fresh ladder: score 0, level just before the swap level (a new block
// can swap again), a fresh grace window. `decided` reports the decision and `tier` is set only when the agent must
// actually go back; `simulated` (observe) decides without touching the tier. Once per run (`deescalated`), never when paused.
export function noteProgress(s: AgentState, cfg: Config = DEFAULT_CONFIG, simulated = false): { state: AgentState; decided?: boolean; tier?: Tier } {
  const swapAt = cfg.levels.indexOf('swap')
  if (cfg.deescalateAfter < 1 || s.paused || s.deescalated || swapAt < 0) return { state: s }
  const above = simulated ? escalated(s, cfg.levels) : tierRank(s.tier) > tierRank(s.startTier)
  if (!above) return { state: s }
  const n = (s.progressSignals ?? 0) + 1
  if (n < cfg.deescalateAfter) return { state: { ...s, progressSignals: n } }
  const back = LADDER[Math.max(tierRank(s.startTier), tierRank(s.tier) - 1)]!
  const state: AgentState = { ...s, tier: simulated ? s.tier : back, progressSignals: 0, deescalated: true,
    score: 0, level: swapAt, stepsSinceAction: 0, errorCounts: {}, ...noEdits(), ...noOutputs(s) }
  return { state, decided: true, tier: simulated ? undefined : back }
}

// An agent may ask for help once per grace window: after a help call (or any intervention) it waits
// for `grace` more tool calls.
export function canAskForHelp(s: AgentState, cfg: Config = DEFAULT_CONFIG): boolean {
  return !s.helped || s.stepsSinceAction >= cfg.grace
}

// A help call jumps straight to the senior consult: the ladder continues after it (the effort level when it is on,
// else the swap; never moves back),
// the score restarts and a fresh grace window begins.
export function afterHelp(s: AgentState, cfg: Config = DEFAULT_CONFIG): AgentState {
  const i = cfg.levels.indexOf('consult')
  return { ...s, helped: true, level: i >= 0 ? Math.max(s.level, i + 1) : s.level, score: 0, stepsSinceAction: 0 }
}

// True once an agent got past the swap level (it swapped at least once, or had none to make) (or past the last one when swap is disabled).
// A de-escalated agent moved its level back but did swap up in this run: it still counts.
// A raised effort alone never counts: the agent kept its model, so the model was not shown to be too weak
// (without swap, the end of the ladder is the last level other than effort).
export function escalated(s: AgentState, levels: readonly Action[]): boolean {
  if (s.deescalated === true) return true
  const i = levels.indexOf('swap')
  if (i >= 0) return s.level > i
  let last = levels.length - 1
  while (last >= 0 && levels[last] === 'effort') last--
  return last >= 0 && s.level > last
}

// The senior model to retry a refused consult on: the other one of opus and sonnet (never haiku).
export function otherSenior(senior: string): 'opus' | 'sonnet' {
  return tierOf(senior) === 'opus' ? 'sonnet' : 'opus'
}

// After a refused consult nothing was given to the agent: the next ladder step is due without a grace window.
export function skipGrace(s: AgentState, cfg: Config = DEFAULT_CONFIG): AgentState {
  return { ...s, stepsSinceAction: Math.max(s.stepsSinceAction, cfg.grace) }
}

// Blocked models: a tier the account refuses (not on the organisation's allowlist, or not offered to it) is
// remembered for the session. It caps the ladder like `maxTier` does: the tier itself and all above are out.
export function refuseTier(blocked: readonly Tier[], tier: Tier): Tier[] {
  return blocked.includes(tier) ? [...blocked] : [...blocked, tier]
}

// The highest tier a swap may reach: `max`, or the one just below the lowest refused tier if that is lower.
export function allowedMax(max: Tier, blocked: readonly Tier[]): Tier {
  if (blocked.length === 0) return max
  const lowest = Math.min(...blocked.map(tierRank))
  return LADDER[Math.max(0, Math.min(tierRank(max), lowest - 1))]!
}

// The tier an agent should run on given the refused ones: its own tier, capped, never below where it started.
export function usableTier(s: AgentState, blocked: readonly Tier[]): Tier {
  const capped = LADDER[Math.min(tierRank(s.tier), tierRank(allowedMax('opus', blocked)))]!
  return tierRank(capped) < tierRank(s.startTier) ? s.startTier : capped
}

// After a swap target was refused: the agent goes back to the tier that worked and its ladder moves to the
// human level, due without a grace window. Without a human level it keeps its place.
export function revertSwap(s: AgentState, to: Tier, cfg: Config = DEFAULT_CONFIG): AgentState {
  const human = cfg.levels.indexOf('human')
  return { ...s, tier: to, level: human >= 0 ? human : s.level, stepsSinceAction: Math.max(s.stepsSinceAction, cfg.grace) }
}

export type ModelFailure = { status?: number | null; error?: string; message?: string }

// What an API failure says about the model: `model` when it is unusable for this account (unknown id, not
// allowed, no permission) so retrying cannot help; `transient` for overload, rate limit, server errors and
// dropped connections, which say nothing about the model; `unknown` when the failure carries no such sign.
export function classifyFailure(f: ModelFailure): 'model' | 'transient' | 'unknown' {
  const err = (f.error ?? '').toLowerCase()
  const msg = (f.message ?? '').toLowerCase()
  const status = typeof f.status === 'number' ? f.status : undefined
  if (err === 'model_not_found') return 'model'
  if (['rate_limit', 'overloaded', 'server_error', 'authentication_failed', 'billing_error'].includes(err)) return 'transient'
  if (status !== undefined && (status === 429 || status >= 500)) return 'transient'
  if (status === 404 || status === 403) return 'model'
  if (/overload|rate.?limit|too many requests|\b(429|5\d\d)\b|timed? ?out|econn|socket|network/.test(msg)) return 'transient'
  if (/not_found|not found|not allowed|allowlist|not available|invalid model|unknown model|permission|not have access|may not exist/.test(msg)) return 'model'
  return status === 400 && /model/.test(msg) ? 'model' : 'unknown'
}

export const isModelRefusal = (f: ModelFailure): boolean => classifyFailure(f) === 'model'

// The senior model for a consult: the configured one, else the other one, skipping refused tiers.
export function pickSenior(senior: string, refused: readonly Tier[]): string | undefined {
  if (!refused.includes(tierOf(senior))) return senior
  const other = otherSenior(senior)
  return refused.includes(other) ? undefined : other
}

// Tools a paused agent may still call: the ones it uses to report or communicate. Pausing at the human level asks the
// agent to stop and summarise for a human, so refusing its hand-back would swallow the very report that is asked for.
export const PAUSE_ALLOWED_TOOLS: readonly string[] = ['SubagentHandback', 'SendMessage', 'TaskList', 'TaskGet', 'TaskUpdate']

export const isPauseAllowedTool = (tool: unknown): boolean => typeof tool === 'string' && PAUSE_ALLOWED_TOOLS.includes(tool)

// Most messages the mod sends to the lead in one session: enough for a few agents climbing the whole ladder,
// small enough that a runaway team cannot flood the lead's context.
export const MAX_LEAD_NOTICES = 10

export type LeadEvent =
  | { kind: 'swap'; tier: Tier }
  | { kind: 'human'; paused: boolean }
  | { kind: 'unavailable'; model: string; stays: Tier }

const NOTICE_INTRO = 'This is an automatic notice from the model-escalator mod the user installed, not tool output; ' +
  'no action is needed unless it says so. '

// One short plain-text message for the lead about an escalated agent. The first one of a session also says what
// these notices are, so the lead does not take them for injected text. Pure.
export function leadMessage(a: { id: string; name?: string; category: string; task: string; taskTitle?: string }, ev: LeadEvent, first: boolean): string {
  const flat = a.task.replace(/\s+/g, ' ').trim()
  // The shared task's title says what the agent works on; the spawn prompt is the fallback.
  const task = a.taskTitle ?? (flat.length > 80 ? `${flat.slice(0, 80)}...` : flat)
  const who = `${agentHead(a)} (${a.category}, task: ${task})`
  const body = ev.kind === 'swap'
    ? `${who} was stuck and now runs on ${ev.tier}.`
    : ev.kind === 'human'
      ? `${who} needs a human: it was told to stop and summarise` +
        (ev.paused ? `, and it is paused; resume it with /escalator resume ${a.id}.` : '.')
      : `${who} was stuck, but ${ev.model} is not available to this account: it stays on ${ev.stays}.`
  return `[model-escalator] ${first ? NOTICE_INTRO : ''}${body}`
}

