// Pure model of the agent network: the lead, its workers (subagents and in-process teammates) and the senior
// that answers consults. No $ calls: it is fed by simple input records that mirror what the hooks already see,
// and it returns a new immutable state each time. A later layout and an SVG renderer read this state; the
// renderer is responsible for escaping every text field (nothing is escaped here, only length-capped).
//
// Wiring map (hook event -> input record):
//   agent.spawn                      -> { type: 'spawn', agentId, label, model }
//   tool.call (before the call)      -> { type: 'tool-start', agentId?, tool, summary? }   summary: path or command
//   tool.call (result)               -> { type: 'tool-end', agentId?, tool }
//   turn.step (result with usage)    -> { type: 'step', agentId?, model, cost }            cost: USD of that request
//   ladder action taken              -> { type: 'ladder', agentId, action, toModel?, level?, score? }
//   consult started / finished       -> { type: 'consult', agentId, phase: 'start' | 'end', model?, cost? }
//   SendMessage / session.send       -> { type: 'message', from?, to?, text? }
//   note appended to the lead        -> { type: 'notice', agentId }
//   stall timer fired                -> { type: 'stall', agentId }
//   human level / resume             -> { type: 'pause' | 'resume', agentId }
//   turn.complete                    -> { type: 'complete', agentId? }
// `agentId` absent means the main loop (the lead). Every record carries `at`, a millisecond timestamp.

import { tierOf, type Tier } from './detector'

export const LEAD_ID = 'lead'
export const SENIOR_ID = 'senior'

export const GRAPH_LIMITS = { workers: 50, events: 100, edges: 200, label: 40, text: 60 } as const

export type NodeKind = 'lead' | 'worker' | 'senior'
export type NodeStatus = 'active' | 'waiting' | 'done' | 'stuck' | 'paused'
export type EdgeKind = 'spawn' | 'message' | 'consult' | 'notice'
export type GraphEventKind = 'spawn' | 'message' | 'consult' | 'swap' | 'nudge' | 'effort' | 'human' | 'notice'
  | 'stall' | 'pause' | 'resume' | 'done'

export type GraphNode = {
  readonly id: string
  readonly kind: NodeKind
  readonly label: string
  readonly model: string
  readonly tier: Tier
  readonly status: NodeStatus
  readonly action: string          // plain words derived from the last event: "reads app.ts", "thinks"...
  readonly level: number           // difficulty level reached on the ladder
  readonly score: number           // difficulty score
  readonly cost: number            // USD so far
  readonly interventions: number   // nudges, consults, effort raises, swaps and human stops received
  readonly consults: number        // consults completed for this node
  readonly since: number           // timestamp of the last status change
}

export type GraphEdge = {
  readonly id: string              // kind|from|to
  readonly kind: EdgeKind
  readonly from: string
  readonly to: string
  readonly count: number
  readonly at: number              // last use, for the renderer's flowing animation
}

export type GraphEvent = {
  readonly seq: number             // strictly increasing, survives queue trimming: the renderer remembers the last one it drew
  readonly kind: GraphEventKind
  readonly at: number
  readonly nodes: readonly string[]
  readonly fromTier?: Tier
  readonly toTier?: Tier
}

export type GraphState = {
  readonly nodes: readonly GraphNode[]
  readonly edges: readonly GraphEdge[]
  readonly events: readonly GraphEvent[]
  readonly seq: number
  readonly collapsed: number       // finished workers folded away to stay under the cap
  readonly dropped: number         // spawns refused because the cap was full of live workers
}

export type LadderAction = 'nudge' | 'consult' | 'effort' | 'swap' | 'human'

export type GraphInput =
  | { type: 'spawn'; at: number; agentId: string; label: string; model: string }
  | { type: 'tool-start'; at: number; agentId?: string; tool: string; summary?: string }
  | { type: 'tool-end'; at: number; agentId?: string; tool?: string }
  | { type: 'step'; at: number; agentId?: string; model: string; cost: number }
  | { type: 'ladder'; at: number; agentId: string; action: LadderAction; toModel?: string; level?: number; score?: number }
  | { type: 'consult'; at: number; agentId: string; phase: 'start' | 'end'; model?: string; cost?: number }
  | { type: 'message'; at: number; from?: string; to?: string; text?: string }
  | { type: 'notice'; at: number; agentId: string }
  | { type: 'stall'; at: number; agentId: string }
  | { type: 'pause'; at: number; agentId: string }
  | { type: 'resume'; at: number; agentId: string }
  | { type: 'complete'; at: number; agentId?: string }

const cap = (s: unknown, n: number): string => (typeof s === 'string' ? s : '').slice(0, n)
const num = (v: unknown, fallback = 0): number => (typeof v === 'number' && Number.isFinite(v) ? v : fallback)
const money = (v: unknown): number => Math.max(0, num(v))
const baseName = (p: string): string => p.split(/[\\/]/).filter(Boolean).pop() ?? ''

// What a tool call means in plain words. `summary` is a path for file tools, a command for Bash.
export function actionText(tool: string, summary?: string): string {
  const s = (summary ?? '').trim()
  const file = baseName(s)
  const withFile = (verb: string, fallback: string) => (file ? `${verb} ${file}` : fallback)
  let text: string
  switch (tool) {
    case 'Read': text = withFile('reads', 'reads a file'); break
    case 'Edit': case 'MultiEdit': case 'NotebookEdit': text = withFile('edits', 'edits a file'); break
    case 'Write': text = withFile('writes', 'writes a file'); break
    case 'Bash': case 'PowerShell': {
      const first = s.split(/\s+/)[0] ?? ''
      if (/(^|[\s/\\])(test|tests|vitest|jest|pytest|mocha)\b/.test(s) || /\bcargo test\b|\bgo test\b/.test(s)) text = 'runs the tests'
      else text = first ? `runs ${baseName(first) || first}` : 'runs a command'
      break
    }
    case 'Grep': text = 'searches the code'; break
    case 'Glob': text = 'lists files'; break
    case 'WebFetch': case 'WebSearch': text = 'browses the web'; break
    case 'Task': case 'Agent': text = 'starts a subagent'; break
    case 'TaskStop': text = 'stops a task'; break
    case 'SendMessage': text = 'sends a message'; break
    case 'ask_for_help': text = 'asks for help'; break
    default: text = `uses ${tool}`
  }
  return text.slice(0, GRAPH_LIMITS.text)
}

const newNode = (id: string, kind: NodeKind, label: string, model: string, at: number): GraphNode => ({
  id, kind, label: cap(label, GRAPH_LIMITS.label), model: cap(model, 100), tier: tierOf(model),
  status: kind === 'senior' ? 'waiting' : 'active', action: kind === 'senior' ? 'idle' : 'starts',
  level: 0, score: 0, cost: 0, interventions: 0, consults: 0, since: at,
})

export function emptyGraph(leadModel: string, at = 0): GraphState {
  return { nodes: [newNode(LEAD_ID, 'lead', 'lead', leadModel, at)], edges: [], events: [], seq: 0, collapsed: 0, dropped: 0 }
}

const find = (s: GraphState, id: string): GraphNode | undefined => s.nodes.find((n) => n.id === id)
const idOf = (agentId: unknown): string => (typeof agentId === 'string' && agentId ? agentId : LEAD_ID)

function patch(s: GraphState, id: string, change: Partial<GraphNode> | ((n: GraphNode) => Partial<GraphNode>)): GraphState {
  return { ...s, nodes: s.nodes.map((n) => (n.id === id ? { ...n, ...(typeof change === 'function' ? change(n) : change) } : n)) }
}

function addEvent(s: GraphState, e: Omit<GraphEvent, 'seq'>): GraphState {
  const seq = s.seq + 1
  const events = [...s.events, { ...e, seq }]
  return { ...s, seq, events: events.length > GRAPH_LIMITS.events ? events.slice(events.length - GRAPH_LIMITS.events) : events }
}

function addEdge(s: GraphState, kind: EdgeKind, from: string, to: string, at: number): GraphState {
  const id = `${kind}|${from}|${to}`
  if (s.edges.some((e) => e.id === id)) {
    return { ...s, edges: s.edges.map((e) => (e.id === id ? { ...e, count: e.count + 1, at } : e)) }
  }
  const edges = [...s.edges, { id, kind, from, to, count: 1, at }]
  return { ...s, edges: edges.length > GRAPH_LIMITS.edges ? edges.slice(edges.length - GRAPH_LIMITS.edges) : edges }
}

const workerCount = (s: GraphState): number => s.nodes.filter((n) => n.kind === 'worker').length

// A done node ignores a tool end and a paused one every activity update until it resumes; a done node that
// starts a tool or takes a step wakes up (see tool-start and step).
const frozen = (n: GraphNode): boolean => n.status === 'done' || n.status === 'paused'

function applySpawn(s: GraphState, i: Extract<GraphInput, { type: 'spawn' }>): GraphState {
  if (typeof i.agentId !== 'string' || !i.agentId || i.agentId === LEAD_ID || i.agentId === SENIOR_ID || find(s, i.agentId)) return s
  let cur = s
  if (workerCount(cur) >= GRAPH_LIMITS.workers) {
    const old = cur.nodes.find((n) => n.kind === 'worker' && n.status === 'done')
    if (!old) return { ...cur, dropped: cur.dropped + 1 }
    cur = {
      ...cur,
      nodes: cur.nodes.filter((n) => n.id !== old.id),
      edges: cur.edges.filter((e) => e.from !== old.id && e.to !== old.id),
      collapsed: cur.collapsed + 1,
    }
  }
  cur = { ...cur, nodes: [...cur.nodes, newNode(i.agentId, 'worker', i.label, i.model, num(i.at))] }
  cur = addEdge(cur, 'spawn', LEAD_ID, i.agentId, num(i.at))
  return addEvent(cur, { kind: 'spawn', at: num(i.at), nodes: [LEAD_ID, i.agentId] })
}

function applyLadder(s: GraphState, i: Extract<GraphInput, { type: 'ladder' }>): GraphState {
  const id = idOf(i.agentId)
  const n = find(s, id)
  if (!n) return s
  const at = num(i.at)
  const base: Partial<GraphNode> = {
    interventions: n.interventions + 1,
    level: i.level === undefined ? n.level : Math.max(0, Math.floor(num(i.level, n.level))),
    score: i.score === undefined ? n.score : num(i.score, n.score),
  }
  switch (i.action) {
    case 'swap': {
      if (typeof i.toModel !== 'string' || !i.toModel) return s
      const toTier = tierOf(i.toModel)
      const cur = addEvent(patch(s, id, { ...base, model: cap(i.toModel, 100), tier: toTier }),
        { kind: 'swap', at, nodes: [id], fromTier: n.tier, toTier })
      return cur
    }
    case 'nudge': return addEvent(patch(s, id, base), { kind: 'nudge', at, nodes: [id] })
    case 'effort': return addEvent(patch(s, id, base), { kind: 'effort', at, nodes: [id] })
    case 'human': return addEvent(patch(s, id, { ...base, status: 'stuck', since: at }), { kind: 'human', at, nodes: [id] })
    case 'consult': return patch(s, id, base) // the consult itself arrives as its own record
    default: return s
  }
}

function applyConsult(s: GraphState, i: Extract<GraphInput, { type: 'consult' }>): GraphState {
  const id = idOf(i.agentId)
  const w = find(s, id)
  if (!w) return s
  const at = num(i.at)
  let cur = s
  if (!find(cur, SENIOR_ID)) {
    const model = typeof i.model === 'string' && i.model ? i.model : 'opus'
    cur = { ...cur, nodes: [...cur.nodes, newNode(SENIOR_ID, 'senior', 'senior', model, at)] }
  } else if (typeof i.model === 'string' && i.model) {
    cur = patch(cur, SENIOR_ID, { model: cap(i.model, 100), tier: tierOf(i.model) })
  }
  if (i.phase === 'start') {
    cur = patch(cur, id, (n) => (n.status === 'done' ? {} : { status: 'waiting', action: 'asks for help', since: at, interventions: n.interventions + 1 }))
    cur = patch(cur, SENIOR_ID, { status: 'active', action: `advises ${w.label}`.slice(0, GRAPH_LIMITS.text), since: at })
    cur = addEdge(cur, 'consult', id, SENIOR_ID, at)
    return addEvent(cur, { kind: 'consult', at, nodes: [id, SENIOR_ID] })
  }
  if (i.phase === 'end') {
    cur = patch(cur, id, (n) => ({ consults: n.consults + 1, ...(n.status === 'waiting' ? { status: 'active' as const, action: 'thinks', since: at } : {}) }))
    return patch(cur, SENIOR_ID, (n) => ({ status: 'waiting', action: 'idle', since: at, cost: n.cost + money(i.cost) }))
  }
  return s
}

function applyStatus(s: GraphState, id: string, status: NodeStatus, kind: GraphEventKind, at: number): GraphState {
  const n = find(s, id)
  if (!n) return s
  return addEvent(patch(s, id, { status, since: at }), { kind, at, nodes: [id] })
}

function reduceUnsafe(s: GraphState, i: GraphInput): GraphState {
  if (!i || typeof i !== 'object') return s
  const at = num((i as { at?: unknown }).at)
  switch (i.type) {
    case 'spawn': return applySpawn(s, i)
    case 'tool-start': {
      const id = idOf(i.agentId)
      const n = find(s, id)
      if (!n || typeof i.tool !== 'string' || !i.tool) return s
      if (n.status === 'paused') return s
      return patch(s, id, { status: 'active', action: actionText(i.tool, i.summary), since: n.status === 'active' ? n.since : at })
    }
    case 'tool-end': {
      const id = idOf(i.agentId)
      const n = find(s, id)
      if (!n || frozen(n)) return s
      return patch(s, id, { action: 'thinks' })
    }
    case 'step': {
      const id = idOf(i.agentId)
      const n = find(s, id)
      if (!n) return s
      const model = typeof i.model === 'string' && i.model ? cap(i.model, 100) : n.model
      // A worker that finished and then steps again was woken (a background command ended, a message came).
      const wake: Partial<GraphNode> = n.status === 'done' ? { status: 'active', since: at } : {}
      return patch(s, id, { model, tier: tierOf(model), cost: n.cost + money(i.cost), ...(n.status === 'paused' ? {} : { action: 'thinks', ...wake }) })
    }
    case 'ladder': return applyLadder(s, i)
    case 'consult': return applyConsult(s, i)
    case 'message': {
      const from = idOf(i.from)
      const to = idOf(i.to)
      if (from === to || !find(s, from) || !find(s, to)) return s
      return addEvent(addEdge(s, 'message', from, to, at), { kind: 'message', at, nodes: [from, to] })
    }
    case 'notice': {
      const id = idOf(i.agentId)
      if (id === LEAD_ID || !find(s, id)) return s
      return addEvent(addEdge(s, 'notice', id, LEAD_ID, at), { kind: 'notice', at, nodes: [id, LEAD_ID] })
    }
    case 'stall': {
      const n = find(s, idOf(i.agentId))
      if (!n || n.status === 'done') return s
      return applyStatus(s, n.id, 'stuck', 'stall', at)
    }
    case 'pause': {
      const n = find(s, idOf(i.agentId))
      if (!n || n.status === 'done') return s
      return applyStatus(s, n.id, 'paused', 'pause', at)
    }
    case 'resume': {
      const n = find(s, idOf(i.agentId))
      if (!n || (n.status !== 'paused' && n.status !== 'stuck')) return s
      return applyStatus(s, n.id, 'active', 'resume', at)
    }
    case 'complete': {
      const n = find(s, idOf(i.agentId))
      if (!n || n.status === 'done') return s
      if (n.kind === 'lead') return patch(s, n.id, { status: 'waiting', action: 'waits', since: at })
      return addEvent(patch(s, n.id, { status: 'done', action: 'done', since: at }), { kind: 'done', at, nodes: [n.id] })
    }
    default: return s
  }
}

// Applies one input record and returns the next state. Never throws: a malformed record leaves the state as is.
export function reduce(state: GraphState, input: GraphInput): GraphState {
  try {
    return reduceUnsafe(state, input)
  } catch {
    return state
  }
}

files.hooks/layout.ts:
// Pure, stable layout of the agent network for the renderers. No $ calls, no clock, no randomness: the same
// graph and the same memory always give the same coordinates.
//
// Geometry: a vertical tree sized for a side pane (LAYOUT.width wide, top-left origin).
//   - the lead sits at the top left; the senior, once a consult happened, on the same row at the right;
//   - workers are full-width rows under the lead, one per slot (slot k is row k), indented to leave a gutter on
//     the left for the tree's trunk; a gutter on the right carries consults and messages between workers;
//   - group nodes ("+N done", "+N more") are shorter rows under the last slot.
// The canvas width never changes; the height grows with the last row in use, downwards only, so no existing
// box ever moves when the canvas grows.
//
// Stability policy. Each worker owns a slot; the slot map comes back with every layout and is passed in again
// next time (`previous`, a Layout or just { slots, retired }, JSON-safe so it can live in $.state). A position
// depends only on the slot, so a node moves only if its slot changes, and a slot changes only like this:
//   - a worker keeps its slot while it runs and after it finishes (finished workers are drawn in place);
//   - workers without a slot (new ones, or with an unusable previous slot) take the lowest free slot, live
//     workers first, then finished ones, each group in spawn order;
//   - when no slot is free, a live newcomer takes the slot of the finished worker that finished first (ties: the
//     lower slot); that worker is retired into "+N done". Nothing else moves;
//   - a retired worker never comes back to the grid, even if a slot frees up later (no flicker);
//   - if every slot holds a live worker, the newcomer waits in "+N more" and is promoted, in spawn order, as soon
//     as a slot frees up or a slot holder finishes;
//   - a worker that disappears from the graph frees its slot; the next newcomer may reuse that position.
// The output is bounded: at most LAYOUT.slots workers, the lead, the senior and two group nodes.
//
// Edges: every visible graph edge is routed as a polyline of horizontal and vertical segments (`points`), from a
// point on the border of its first box (x1, y1) to a point on the border of the second (x2, y2), through lanes
// that never cross a box: lead <-> row on a lane of the left gutter per kind (spawn, message, notice), row <->
// senior along the right edge, row <-> row through the right gutter. An endpoint that is hidden in a group is
// routed to that group node; parallel edges that end up between the same pair are merged (counts summed, latest
// `at`). An edge whose endpoints are both hidden, or that would loop on one node, is dropped.

import { LEAD_ID, SENIOR_ID, type EdgeKind, type GraphState, type NodeKind } from './graph'

export const LAYOUT = (() => {
  const width = 440
  const margin = 16
  const indent = 50                      // left edge of the rows: the gutter before it carries the tree's trunk
  const gutter = 24                      // right gutter: consults and messages between workers
  const rows = 30
  return {
    width, margin, indent, gutter, rows, slots: rows, members: 50,
    topW: 196,                           // lead and senior
    nodeW: width - margin - gutter - indent,
    nodeH: 50, groupH: 32, gapY: 10, topGap: 22,
    // x of the vertical lanes: the left ones start under the lead, one per edge kind; `right` runs in the right
    // gutter between rows, `senior` along the right edge up to the senior's bottom border
    lanes: { spawn: 24, message: 32, notice: 40, right: width - margin - gutter + 10, senior: width - margin - 6 },
  } as const
})()

export const GROUP_DONE_ID = 'group:done'
export const GROUP_MORE_ID = 'group:more'

export type GroupKind = 'done' | 'more'

export type LayoutNode = {
  readonly id: string
  readonly kind: NodeKind | 'group'
  readonly x: number
  readonly y: number
  readonly w: number
  readonly h: number
  readonly cx: number
  readonly cy: number
  readonly slot?: number                 // workers only
  readonly group?: GroupKind             // group nodes only
  readonly count?: number                // group nodes: hidden workers, including those the graph already folded away
  readonly label?: string                // group nodes: "+3 done", "+2 more"
  readonly members?: readonly string[]   // group nodes: ids of the hidden workers still in the graph, spawn order
}

export type LayoutEdge = {
  readonly id: string                    // kind|from|to, after routing
  readonly kind: EdgeKind
  readonly from: string                  // visible node ids (a group id when rerouted)
  readonly to: string
  readonly x1: number
  readonly y1: number
  readonly x2: number
  readonly y2: number
  readonly count: number
  readonly at: number
  readonly rerouted: boolean
  readonly points: readonly Point[]      // the route from (x1, y1) to (x2, y2): horizontal and vertical segments
}

export type Point = readonly [number, number]

export type LayoutMemory = {
  readonly slots?: Readonly<Record<string, number>>
  readonly retired?: readonly string[]
}

// Nodes are listed lead first, then workers by slot, then the groups, then the senior: a text tree can reuse it.
export type Layout = {
  readonly width: number
  readonly height: number
  readonly nodes: readonly LayoutNode[]
  readonly edges: readonly LayoutEdge[]
  readonly slots: Readonly<Record<string, number>>
  readonly retired: readonly string[]
}

const EDGE_KINDS: readonly string[] = ['spawn', 'message', 'consult', 'notice']

const WIDTH = LAYOUT.width
const rowY = (r: number): number => LAYOUT.margin + LAYOUT.nodeH + LAYOUT.topGap + r * (LAYOUT.nodeH + LAYOUT.gapY)

function box(id: string, kind: LayoutNode['kind'], x: number, y: number, w: number, h: number, extra: Partial<LayoutNode> = {}): LayoutNode {
  return { id, kind, x, y, w, h, cx: x + w / 2, cy: y + h / 2, ...extra }
}

const leadBox = (): LayoutNode => box(LEAD_ID, 'lead', LAYOUT.margin, LAYOUT.margin, LAYOUT.topW, LAYOUT.nodeH)
const seniorBox = (): LayoutNode =>
  box(SENIOR_ID, 'senior', LAYOUT.width - LAYOUT.margin - LAYOUT.topW, LAYOUT.margin, LAYOUT.topW, LAYOUT.nodeH)
const slotBox = (id: string, slot: number): LayoutNode => box(id, 'worker', LAYOUT.indent, rowY(slot), LAYOUT.nodeW, LAYOUT.nodeH, { slot })

// Group rows sit under the last slot: "+N done" first, then "+N more", each always at the same place.
function groupBox(group: GroupKind, count: number, members: readonly string[]): LayoutNode {
  const y = rowY(LAYOUT.rows) + (group === 'done' ? 0 : LAYOUT.groupH + LAYOUT.gapY)
  return box(group === 'done' ? GROUP_DONE_ID : GROUP_MORE_ID, 'group', LAYOUT.indent, y, LAYOUT.nodeW, LAYOUT.groupH, {
    group, count, label: `+${count} ${group}`, members,
  })
}

const isRecord = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v)
const own = (o: Record<string, unknown>, k: string): unknown => (Object.prototype.hasOwnProperty.call(o, k) ? o[k] : undefined)
const finite = (v: unknown, fallback: number): number => (typeof v === 'number' && Number.isFinite(v) ? v : fallback)
const counter = (v: unknown): number => Math.max(0, Math.floor(finite(v, 0)))

// Fallback for a pair no lane serves (the lead and the senior): bottom to top when one box is below the other,
// side to side otherwise, with an elbow halfway so every segment stays horizontal or vertical.
function direct(a: LayoutNode, b: LayoutNode): Point[] {
  if (b.y >= a.y + a.h || a.y >= b.y + b.h) {
    const down = b.y >= a.y + a.h
    const y1 = down ? a.y + a.h : a.y
    const y2 = down ? b.y : b.y + b.h
    const my = (y1 + y2) / 2
    return a.cx === b.cx ? [[a.cx, y1], [b.cx, y2]] : [[a.cx, y1], [a.cx, my], [b.cx, my], [b.cx, y2]]
  }
  const right = b.x >= a.x + a.w
  const x1 = right ? a.x + a.w : a.x
  const x2 = right ? b.x : b.x + b.w
  const mx = (x1 + x2) / 2
  return a.cy === b.cy ? [[x1, a.cy], [x2, b.cy]] : [[x1, a.cy], [mx, a.cy], [mx, b.cy], [x2, b.cy]]
}

const isRow = (n: LayoutNode): boolean => n.kind === 'worker' || n.kind === 'group'

// The route of one edge: the first point on `a`'s border, the last on `b`'s.
function route(kind: EdgeKind, a: LayoutNode, b: LayoutNode): Point[] {
  const L = LAYOUT.lanes
  const left = kind === 'spawn' ? L.spawn : kind === 'notice' ? L.notice : L.message
  if (a.kind === 'lead' && isRow(b)) return [[left, a.y + a.h], [left, b.cy], [b.x, b.cy]]
  if (isRow(a) && b.kind === 'lead') return [[a.x, a.cy], [left, a.cy], [left, b.y + b.h]]
  if (isRow(a) && b.kind === 'senior') return [[a.x + a.w, a.cy], [L.senior, a.cy], [L.senior, b.y + b.h]]
  if (a.kind === 'senior' && isRow(b)) return [[L.senior, a.y + a.h], [L.senior, b.cy], [b.x + b.w, b.cy]]
  if (isRow(a) && isRow(b)) return [[a.x + a.w, a.cy], [L.right, a.cy], [L.right, b.cy], [b.x + b.w, b.cy]]
  return direct(a, b)
}

type Worker = { id: string; done: boolean; since: number }
type Place = number | GroupKind

function layoutUnsafe(graph: GraphState, previous: LayoutMemory | undefined): Layout {
  const g: Record<string, unknown> = isRecord(graph) ? graph : {}
  const rawNodes = Array.isArray(g.nodes) ? (g.nodes as unknown[]) : []

  const workers: Worker[] = []
  const seen = new Set<string>([LEAD_ID, SENIOR_ID, GROUP_DONE_ID, GROUP_MORE_ID])
  let hasSenior = false
  for (const n of rawNodes) {
    if (!isRecord(n) || typeof n.id !== 'string') continue
    if (n.kind === 'senior' && n.id === SENIOR_ID) hasSenior = true
    if (n.kind !== 'worker' || !n.id || seen.has(n.id)) continue
    seen.add(n.id)
    workers.push({ id: n.id, done: n.status === 'done', since: finite(n.since, 0) })
  }

  const mem: Record<string, unknown> = isRecord(previous) ? previous : {}
  const prevSlots: Record<string, unknown> = isRecord(mem.slots) ? mem.slots : {}
  const retired = new Set<string>(Array.isArray(mem.retired) ? mem.retired.filter((x): x is string => typeof x === 'string') : [])

  const place = new Map<string, Place>()
  const holder: (Worker | undefined)[] = Array.from({ length: LAYOUT.slots }, () => undefined)

  // 1. keep the previous slots (the first claimant in spawn order wins a duplicated slot)
  for (const w of workers) {
    const s = own(prevSlots, w.id)
    if (typeof s === 'number' && Number.isInteger(s) && s >= 0 && s < LAYOUT.slots && !holder[s]) {
      holder[s] = w
      place.set(w.id, s)
    }
  }
  const freeSlot = (): number => holder.findIndex((h) => h === undefined)

  // 2. live workers without a slot: a free slot, else the slot of the earliest finished worker, else "+N more"
  for (const w of workers) {
    if (place.has(w.id) || w.done) continue
    let s = freeSlot()
    if (s < 0) {
      let victim = -1
      holder.forEach((h, i) => {
        if (h?.done && (victim < 0 || h.since < (holder[victim]?.since ?? 0))) victim = i
      })
      if (victim >= 0) {
        const old = holder[victim]
        if (old) place.set(old.id, 'done')
        s = victim
      }
    }
    if (s >= 0) {
      holder[s] = w
      place.set(w.id, s)
    } else {
      place.set(w.id, 'more')
    }
  }

  // 3. finished workers without a slot: retired ones stay folded, the others take a free slot if there is one
  for (const w of workers) {
    if (place.has(w.id)) continue
    const s = retired.has(w.id) ? -1 : freeSlot()
    if (s >= 0) {
      holder[s] = w
      place.set(w.id, s)
    } else {
      place.set(w.id, 'done')
    }
  }

  const doneMembers = workers.filter((w) => place.get(w.id) === 'done').map((w) => w.id)
  const moreMembers = workers.filter((w) => place.get(w.id) === 'more').map((w) => w.id)
  const doneCount = doneMembers.length + counter(g.collapsed)
  const moreCount = moreMembers.length + counter(g.dropped)

  const nodes: LayoutNode[] = [leadBox()]
  holder.forEach((w, s) => {
    if (w) nodes.push(slotBox(w.id, s))
  })
  if (doneCount > 0) nodes.push(groupBox('done', doneCount, doneMembers.slice(0, LAYOUT.members)))
  if (moreCount > 0) nodes.push(groupBox('more', moreCount, moreMembers.slice(0, LAYOUT.members)))
  if (hasSenior) nodes.push(seniorBox())

  const byId = new Map(nodes.map((n) => [n.id, n]))
  const resolve = (id: unknown): { id: string; hidden: boolean } | undefined => {
    if (typeof id !== 'string') return undefined
    const p = place.get(id)
    if (p === 'done') return byId.has(GROUP_DONE_ID) ? { id: GROUP_DONE_ID, hidden: true } : undefined
    if (p === 'more') return byId.has(GROUP_MORE_ID) ? { id: GROUP_MORE_ID, hidden: true } : undefined
    return byId.has(id) ? { id, hidden: false } : undefined
  }

  type Acc = { kind: EdgeKind; from: string; to: string; count: number; at: number; rerouted: boolean }
  const merged = new Map<string, Acc>()
  for (const e of Array.isArray(g.edges) ? (g.edges as unknown[]) : []) {
    if (!isRecord(e) || typeof e.kind !== 'string' || !EDGE_KINDS.includes(e.kind)) continue
    const a = resolve(e.from)
    const b = resolve(e.to)
    if (!a || !b || (a.hidden && b.hidden) || a.id === b.id) continue
    const kind = e.kind as EdgeKind
    const key = `${kind}|${a.id}|${b.id}`
    const count = Math.max(1, counter(e.count))
    const at = finite(e.at, 0)
    const cur = merged.get(key)
    if (cur) {
      cur.count += count
      cur.at = Math.max(cur.at, at)
      cur.rerouted = cur.rerouted || a.hidden || b.hidden
    } else {
      merged.set(key, { kind, from: a.id, to: b.id, count, at, rerouted: a.hidden || b.hidden })
    }
  }
  const edges: LayoutEdge[] = []
  for (const [id, m] of merged) {
    const a = byId.get(m.from)
    const b = byId.get(m.to)
    if (!a || !b) continue
    const points = route(m.kind, a, b)
    const [x1, y1] = points[0]!
    const [x2, y2] = points[points.length - 1]!
    edges.push({ id, kind: m.kind, from: m.from, to: m.to, x1, y1, x2, y2, count: m.count, at: m.at, rerouted: m.rerouted, points })
  }

  const bottom = nodes.reduce((y, n) => Math.max(y, n.y + n.h), 0)
  const slots = Object.fromEntries(holder.flatMap((w, s) => (w ? [[w.id, s] as const] : [])))
  return { width: WIDTH, height: bottom + LAYOUT.margin, nodes, edges, slots, retired: doneMembers.slice(0, LAYOUT.members) }
}

// Lays out the graph, keeping the slots of `previous` (the last Layout, or the { slots, retired } part of it).
// Never throws: on malformed input it degrades to the lead alone.
export function layoutGraph(graph: GraphState, previous?: LayoutMemory): Layout {
  try {
    return layoutUnsafe(graph, previous)
  } catch {
    const lead = leadBox()
    return { width: WIDTH, height: lead.y + lead.h + LAYOUT.margin, nodes: [lead], edges: [], slots: {}, retired: [] }
  }
}

