{
  "name": "model-escalator",
  "version": "1.3.0",
  "description": "Run cheap models in parallel and escalate only when they get stuck: nudge, senior consult, hot model swap. Measures savings and learns the right model per task.",
  "author": {
    "name": "Alessandro Tozzi",
    "email": "261738626+atozzi-dev@users.noreply.github.com"
  },
  "repository": "https://github.com/atozzi-dev/model-escalator",
  "homepage": "https://github.com/atozzi-dev/model-escalator#readme",
  "keywords": [
    "subagents",
    "model-selection",
    "escalation",
    "cost",
    "agent-teams"
  ],
  "license": "MIT",
  "types": "./types/index.d.ts",
  "userConfig": {
    "thresholdHaiku": {
      "type": "number",
      "title": "Haiku difficulty threshold",
      "description": "Difficulty score at which an agent that started on Haiku gets the next intervention.",
      "default": 3
    },
    "thresholdSonnet": {
      "type": "number",
      "title": "Sonnet difficulty threshold",
      "description": "Difficulty score at which an agent that started on Sonnet gets the next intervention.",
      "default": 5
    },
    "thresholdOpus": {
      "type": "number",
      "title": "Opus difficulty threshold",
      "description": "Difficulty score at which an agent that started on Opus gets the next intervention.",
      "default": 7
    },
    "graceSteps": {
      "type": "number",
      "title": "Grace steps",
      "description": "Steps to wait after an intervention before the next one.",
      "default": 4
    },
    "oscillationEdits": {
      "type": "number",
      "title": "Edits before oscillation",
      "description": "Edits of the same file made after a failed attempt (since the previous edit of that file), without progress, tolerated before each further such edit raises the difficulty score. Edits with no failure in between never count.",
      "default": 5
    },
    "stallMinutes": {
      "type": "number",
      "title": "Stall window (minutes)",
      "description": "Minutes without any event after which a running agent is reported as stalled and gets the next ladder note on its next tool call. A tool call still running counts as activity until three times this long. Nothing is reported while the session is closed or the account is at its usage limit.",
      "default": 10
    },
    "verifyCommand": {
      "type": "string",
      "title": "Verification command",
      "description": "Optional check run at the end of each tracked agent's run (split on spaces, quotes group, no shell). A non-zero exit counts as a failed run for learning; a command that cannot start or times out is ignored. Empty turns it off.",
      "default": ""
    },
    "verifyTimeoutSeconds": {
      "type": "number",
      "title": "Verification timeout (seconds)",
      "description": "How long the verification command may run before it is abandoned and ignored (at most 600).",
      "default": 120
    },
    "reviewRate": {
      "type": "number",
      "title": "Review rate",
      "description": "Share of the runs of cheaper models (started below the lead's or baseline model) whose diff a senior model reviews and scores 1-5, from 0 to 1 (0.1 reviews about one run in ten). Each review costs one senior call. 0 is off.",
      "default": 0
    },
    "reviewModel": {
      "type": "string",
      "title": "Review model",
      "description": "Model that reviews a sampled run (alias or full id). Empty uses the senior model.",
      "default": ""
    },
    "seniorModel": {
      "type": "string",
      "title": "Senior model",
      "description": "Model asked for advice at the consult level (alias or full id).",
      "default": "opus"
    },
    "levels": {
      "type": "string",
      "title": "Enabled levels",
      "description": "Comma-separated escalation levels, from: nudge, consult, swap, human. Disabled levels are skipped.",
      "default": "nudge,consult,swap,human"
    },
    "maxTier": {
      "type": "string",
      "title": "Highest swap tier",
      "description": "Highest model tier an agent may be swapped up to: haiku, sonnet or opus. Agents already at this tier skip the swap level. Never above opus.",
      "default": "opus"
    },
    "prudentTokenRatio": {
      "type": "number",
      "title": "Prudent token ratio",
      "description": "Share of the tokens a stronger baseline model is assumed to need, used for the prudent savings estimate (0 to 1).",
      "default": 0.65
    },
    "prices": {
      "type": "string",
      "title": "Price overrides",
      "description": "Optional JSON overriding USD per million token rates, e.g. {\"sonnet\":{\"input\":3,\"output\":15}}. Rates: input, output, cacheRead, cacheWrite5m, cacheWrite1h.",
      "default": ""
    },
    "modelIds": {
      "type": "string",
      "title": "Model ids",
      "description": "Optional JSON with the full model id to send on a swap, per tier, e.g. {\"sonnet\":\"us.anthropic.claude-sonnet-...\",\"opus\":\"...\"}. Needed on Bedrock, Vertex or a gateway when swaps report a model not available. Beats ids seen in the session and the defaults.",
      "default": ""
    },
    "maxConsultsPerAgent": {
      "type": "number",
      "title": "Consults per agent",
      "description": "Senior consults one agent may get. A refused call and its retry count as one consult. Once reached, the ladder skips the consult level and ask_for_help answers that no further consult is available. 0 allows none.",
      "default": 3
    },
    "maxConsultsPerSession": {
      "type": "number",
      "title": "Consults per session",
      "description": "Senior consults across all agents of the session, with the same counting. 0 allows none.",
      "default": 20
    },
    "pauseAtHuman": {
      "type": "boolean",
      "title": "Pause at the human level",
      "description": "When an agent reaches the human level, refuse all its further tool calls until you resume it with /escalator resume <id> (or all). Off keeps the note only.",
      "default": true
    },
    "deescalateAfter": {
      "type": "number",
      "title": "Return to a cheaper model after progress",
      "description": "Progress signals (failing tests dropping or reaching 0) after which an agent that was swapped up goes back one tier, once per run. Off by default: returning to a cheaper model rewrites the prompt cache and may bring the block back. 0 is off.",
      "default": 0
    },
    "learningHalfLifeDays": {
      "type": "number",
      "title": "Learning half-life (days)",
      "description": "Days after which learned evidence counts half, so a category is not stuck on a stronger model forever because of old runs. 0 never forgets.",
      "default": 30
    },
    "explore": {
      "type": "number",
      "title": "Explore cheaper models",
      "description": "From 0 to 1: how often a task starts on the cheaper model that learning had ruled out, to check whether it became good enough. It only lowers a tier that learning raised, never below the model you asked for, and is rarer the stronger the evidence (Thompson sampling). Some tasks deliberately run on a weaker model. 0 is off.",
      "default": 0
    },
    "respectExplicitModel": {
      "type": "boolean",
      "title": "Respect a model asked for explicitly",
      "description": "When on and the Agent call names a model, the task starts on it: learning and exploration do not change the starting model (the log says what they would have suggested). The ladder still moves the agent up when it is stuck. Off by default: the lead usually names a cheap model itself, and learning is there to correct that choice. Turn it on for strict respect of what was asked.",
      "default": false
    },
    "learnByCost": {
      "type": "boolean",
      "title": "Choose the model by cost per accepted run",
      "description": "Once the mod has enough priced runs of a task category on the models involved, a task starts on the model with the lowest cost per accepted run (the mean cost of a run divided by the share of runs that were accepted). Off keeps the rule that only looks at how often a model failed.",
      "default": true
    },
    "modelCategories": {
      "type": "boolean",
      "title": "Classify tasks with a small model",
      "description": "Label each new subagent task (tests, bugfix, feature, review, ...) with one short call to a small model instead of keywords only, so the mod learns per task kind more accurately. Adds about a second to a spawn that is not in its cache; the call's cost is not counted in the report. Off by default.",
      "default": false
    },
    "minReviewScore": {
      "type": "number",
      "title": "Lowest review score of an accepted run",
      "description": "From 1 to 5: a run reviewed below this score (reviewRate) counts as not accepted when the mod learns which model to use. 3 is works but needs changes.",
      "default": 3
    },
    "reworkWindowMinutes": {
      "type": "number",
      "title": "Rework window (minutes)",
      "description": "When the lead edits, within this many minutes, a file a cheaper agent wrote in its run, the run counts as reworked: it is moved to not accepted for learning and shown by /escalator stats. Edits you make outside Claude Code are not visible. 0 is off.",
      "default": 30
    },
    "effortStep": {
      "type": "boolean",
      "title": "Raise the effort before a model swap",
      "description": "Adds a level between the senior consult and the model swap: the stuck agent keeps its model and its requests carry a higher effort (one step above their own, at least the effort boost) until its next swap. Skipped for a model that takes no effort or a request already at max. Off by default until measured: a higher effort costs more output tokens and a change of effort rewrites the prompt cache.",
      "default": false
    },
    "notifyLead": {
      "type": "boolean",
      "title": "Tell the lead about escalations",
      "description": "Add a short notice to the main conversation, read by the lead, whenever an agent is swapped to a stronger model, cannot be (the model is not available) or needs a human. At most 10 messages per session; active mode only. Off keeps the log and the toasts only.",
      "default": true
    },
    "effortBoost": {
      "type": "string",
      "title": "Effort boost",
      "description": "Lowest effort the effort level raises a request to: low, medium, high, xhigh or max. The request always goes at least one step above its own effort.",
      "default": "high"
    },
    "consultBudgetUsd": {
      "type": "number",
      "title": "Consult budget (USD)",
      "description": "Dollars the senior calls may cost in the session, retried calls included. Once reached, no further consult. 0 means no dollar limit.",
      "default": 0
    },
    "recordSessions": {
      "type": "number",
      "title": "Recorded sessions",
      "description": "Keep a recording of what the mod observed in the last N sessions (at most 50), so /escalator replay can try other thresholds and levels on them without spending. Stored in the plugin's store, capped in size; error signatures are redacted, commands, outputs, prompts and file paths are not kept. Works in every mode except off. 0 is off.",
      "default": 0
    }
  }
}
